import 'package:mad_flutter_practicum/domain/domain.dart';

class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> with SingleTickerProviderStateMixin {
  late Future<(List<CurrencyModel>, List<NewsModel>)> _dashboardFuture;

  late final AnimationController _fadeController;
  late final Animation<double> _fadeAnimation;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
    _fadeAnimation = CurvedAnimation(parent: _fadeController, curve: Curves.easeIn);
  }

  void _initData() {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    _dashboardFuture = Future.wait([
      currencyRepository.fetchRates(const CurrencyPageRequest()),
      newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
    ]).then((List<dynamic> results) {
      final CurrencyPage page = results[0] as CurrencyPage;
      final List<NewsModel> news = results[1] as List<NewsModel>;

      _fadeController.forward();

      return (page.items, news);
    });
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;

    return Scaffold(
      appBar: AppBar(title: Text(loc.dashboard)),
      body: FutureBuilder<(List<CurrencyModel>, List<NewsModel>)>(
        future: _dashboardFuture,
        builder: (BuildContext context, AsyncSnapshot<(List<CurrencyModel>, List<NewsModel>)> snapshot) {
          if (!snapshot.hasData) {
            return const Center(child: CircularProgressIndicator());
          }

          final List<CurrencyModel> currencies = snapshot.data!.$1;
          final List<NewsModel> news = snapshot.data!.$2;

          return FadeTransition(
            opacity: _fadeAnimation,
            child: ListView.builder(
              itemCount: currencies.length + news.length,
              itemBuilder: (BuildContext context, int index) {
                if (index < currencies.length) {
                  final CurrencyModel currency = currencies[index];
                  return Padding(
                    key: ValueKey(currency.id),
                    padding: const EdgeInsets.fromLTRB(20, 16, 20, 0),
                    child: CurrencyCard(model: currency),
                  );
                } else {
                  final NewsModel newsItem = news[index - currencies.length];
                  return Padding(
                    key: ValueKey(newsItem.link),
                    padding: const EdgeInsets.fromLTRB(20, 16, 20, 0),
                    child: NewsCard(model: newsItem),
                  );
                }
              },
            ),
          );
        },
      ),
    );
  }
}
